-- PRODUCTION DRAFT — monitor ID format validation for pair_monitor_device
-- Target: sodgzkablshladvbtnes (Precios al Día production).
-- Status: NOT APPLIED. Requires a verified backup and explicit approval.
--
-- Purpose: accept only the two monitor ID formats the app produces:
--   * legacy/current box-style fingerprints: PDA-<8..64 hex> or PDA-V2-<8..64 hex>
--   * monitor profile IDs generated by PairingScanScreen: mon-<uuid-like>
-- Current production accepts any non-empty ID. This draft only adds validation.
--
-- Additive and grant-neutral:
--   * CREATE OR REPLACE keeps the existing owner, EXECUTE grants and search_path.
--   * No table, index, policy, or row is changed.
--   * Behavior for valid IDs is identical to the current production function.
--
-- Preflight (read-only, already checked 2026-10-12): all 3 active monitor_device_id
-- values and 16 of 19 primary_device_id values match this pattern. The 3 non-matching
-- primary IDs are e2e test rows pending cleanup; they are not real customer boxes.

BEGIN;

CREATE OR REPLACE FUNCTION public.pair_monitor_device(p_token text, p_monitor_device_id text)
RETURNS json
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    v_monitor uuid := auth.uid();
    v_monitor_id text := trim(p_monitor_device_id);
    v_pairing public.device_pairings%ROWTYPE;
BEGIN
    IF v_monitor IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'Sesión no autenticada.');
    END IF;

    -- Accept only PDA- fingerprints (legacy hex or V2) and mon- profile IDs.
    IF v_monitor_id IS NULL
       OR length(v_monitor_id) < 8
       OR length(v_monitor_id) > 160
       OR NOT (
            v_monitor_id ~ '^PDA-(V2-)?[0-9A-Fa-f]{8,64}$'
         OR v_monitor_id ~ '^mon-[0-9A-Za-z-]{8,156}$'
       ) THEN
        RETURN json_build_object('success', false, 'message', 'Identificador de monitor inválido.');
    END IF;

    IF p_token IS NULL OR length(trim(p_token)) < 16 OR length(trim(p_token)) > 64 THEN
        RETURN json_build_object('success', false, 'message', 'Código inválido.');
    END IF;

    SELECT *
    INTO v_pairing
    FROM public.device_pairings
    WHERE token_hash = encode(digest(upper(trim(p_token)), 'sha256'), 'hex')
      AND token_expires_at > now()
      AND token_used_at IS NULL
      AND revoked_at IS NULL
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN json_build_object('success', false, 'message', 'El código expiró o ya fue utilizado.');
    END IF;

    IF v_pairing.monitor_auth_id IS NOT NULL
       AND v_pairing.monitor_auth_id <> v_monitor THEN
        RETURN json_build_object('success', false, 'message', 'El vínculo ya está ocupado.');
    END IF;

    UPDATE public.device_pairings
    SET monitor_device_id = v_monitor_id,
        monitor_auth_id = v_monitor,
        pairing_token = NULL,
        token_hash = NULL,
        token_used_at = now(),
        paired_at = now()
    WHERE id = v_pairing.id;

    RETURN json_build_object(
        'success', true,
        'primary_device_id', v_pairing.primary_device_id
    );
END;
$function$;

COMMIT;
